import { parse as parseToml, stringify as stringifyToml } from "smol-toml";
import { stringify as stringifyYaml } from "yaml";

import { isPortableAgentName } from "./definitions.js";
import { parseFrontmatter } from "./frontmatter.js";
import type { CanonicalAgent, TargetName, TargetOverlay } from "./types.js";

const CODEX_GENERATED_COMMENT =
  "# Generated by Overlord; edit the canonical .agents definition instead.\n";

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function isObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function isTable(value: unknown): value is Record<string, unknown> {
  return isObject(value) && !(value instanceof Date);
}

function isArrayOfTables(value: unknown): value is Record<string, unknown>[] {
  return Array.isArray(value) && value.length > 0 && value.every(isTable);
}

function entriesObject(entries: Iterable<readonly [string, unknown]>): Record<string, unknown> {
  return Object.fromEntries(entries);
}

function normalizeBody(body: string): string {
  const lf = body.replace(/\r\n?/g, "\n");
  return `${lf.replace(/\n+$/g, "")}\n`;
}

function assertCommonFields(agent: CanonicalAgent): void {
  if (typeof agent.name !== "string" || agent.name.length === 0) {
    throw new TypeError("Agent name must be a non-empty string.");
  }
  if (typeof agent.description !== "string" || agent.description.trim().length === 0) {
    throw new TypeError(`Agent '${agent.name}' description must be a non-empty string.`);
  }
  if (typeof agent.body !== "string") {
    throw new TypeError(`Agent '${agent.name}' instructions must be a string.`);
  }
}

function enabledOverlay(agent: CanonicalAgent, target: TargetName): TargetOverlay {
  const overlay = agent.targets[target];
  if (overlay === false) throw new Error(`Agent '${agent.name}' target '${target}' is disabled.`);
  if (!isObject(overlay)) throw new TypeError(`Agent '${agent.name}' target '${target}' must be a mapping or false.`);
  return overlay;
}

function assertNoReservedFields(
  agent: CanonicalAgent,
  target: TargetName,
  overlay: TargetOverlay,
): void {
  const reserved = target === "claude"
    ? ["name", "description"]
    : ["name", "description", "developer_instructions"];
  for (const field of reserved) {
    if (Object.hasOwn(overlay, field)) {
      throw new Error(
        `Agent '${agent.name}' target '${target}' cannot override common field '${field}'.`,
      );
    }
  }
}

function orderedYamlValue(value: unknown, ancestors: ReadonlySet<object>): unknown {
  if (value === undefined || typeof value === "function" || typeof value === "symbol") {
    throw new TypeError(`Cannot render YAML value of type '${typeof value}'.`);
  }
  if (value === null || typeof value !== "object" || value instanceof Date) return value;
  if (ancestors.has(value)) throw new TypeError("Cannot render a cyclic YAML value.");

  const nextAncestors = new Set(ancestors);
  nextAncestors.add(value);
  if (Array.isArray(value)) {
    return value.map((entry) => orderedYamlValue(entry, nextAncestors));
  }
  if (!isObject(value)) throw new TypeError("Cannot render a non-mapping YAML object.");

  return entriesObject(
    Object.keys(value)
      .sort(compareText)
      .map((key) => [key, orderedYamlValue(value[key], nextAncestors)] as const),
  );
}

function yamlDocument(value: Record<string, unknown>): string {
  return stringifyYaml(value, {
    lineWidth: 0,
    sortMapEntries: false,
  });
}

/** Render a canonical agent into Claude Code's Markdown subagent format. */
export function renderClaudeAgent(agent: CanonicalAgent): string {
  assertCommonFields(agent);
  const overlay = enabledOverlay(agent, "claude");
  assertNoReservedFields(agent, "claude", overlay);

  const attributes = entriesObject([
    ["name", agent.name],
    ["description", agent.description],
    ...Object.keys(overlay)
      .sort(compareText)
      .map((key) => [key, orderedYamlValue(overlay[key], new Set())] as const),
  ]);
  return `---\n${yamlDocument(attributes)}---\n\n${normalizeBody(agent.body)}`;
}

function validateTomlValue(value: unknown, ancestors: ReadonlySet<object>): void {
  if (value === null || value === undefined) {
    throw new TypeError("TOML cannot represent null or undefined values.");
  }
  if (typeof value === "function" || typeof value === "symbol") {
    throw new TypeError(`TOML cannot represent values of type '${typeof value}'.`);
  }
  if (typeof value !== "object" || value instanceof Date) return;
  if (ancestors.has(value)) throw new TypeError("Cannot render a cyclic TOML value.");

  const nextAncestors = new Set(ancestors);
  nextAncestors.add(value);
  if (Array.isArray(value)) {
    for (const entry of value) validateTomlValue(entry, nextAncestors);
    return;
  }
  if (!isTable(value)) throw new TypeError("TOML objects must be mappings.");
  for (const entry of Object.values(value)) validateTomlValue(entry, nextAncestors);
}

function orderedInlineTomlValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(orderedInlineTomlValue);
  if (!isTable(value)) return value;
  return orderedTomlTable(value);
}

function orderedTomlTable(table: Record<string, unknown>): Record<string, unknown> {
  const scalarKeys: string[] = [];
  const tableKeys: string[] = [];
  for (const key of Object.keys(table)) {
    const value = table[key];
    if (isTable(value) || isArrayOfTables(value)) tableKeys.push(key);
    else scalarKeys.push(key);
  }
  scalarKeys.sort(compareText);
  tableKeys.sort(compareText);

  return entriesObject([
    ...scalarKeys.map((key) => [key, orderedInlineTomlValue(table[key])] as const),
    ...tableKeys.map((key) => {
      const value = table[key];
      return [
        key,
        Array.isArray(value)
          ? value.map((entry) => orderedTomlTable(entry))
          : orderedTomlTable(value as Record<string, unknown>),
      ] as const;
    }),
  ]);
}

/** Render a canonical agent into Codex CLI's TOML custom-agent format. */
export function renderCodexAgent(agent: CanonicalAgent): string {
  assertCommonFields(agent);
  const overlay = enabledOverlay(agent, "codex");
  assertNoReservedFields(agent, "codex", overlay);
  validateTomlValue(overlay, new Set());

  const scalarKeys: string[] = [];
  const tableKeys: string[] = [];
  for (const key of Object.keys(overlay)) {
    const value = overlay[key];
    if (isTable(value) || isArrayOfTables(value)) tableKeys.push(key);
    else scalarKeys.push(key);
  }
  scalarKeys.sort(compareText);
  tableKeys.sort(compareText);

  const document = entriesObject([
    ["name", agent.name],
    ["description", agent.description],
    ...scalarKeys.map((key) => [key, orderedInlineTomlValue(overlay[key])] as const),
    ["developer_instructions", normalizeBody(agent.body)],
    ...tableKeys.map((key) => {
      const value = overlay[key];
      return [
        key,
        Array.isArray(value)
          ? value.map((entry) => orderedTomlTable(entry))
          : orderedTomlTable(value as Record<string, unknown>),
      ] as const;
    }),
  ]);

  return CODEX_GENERATED_COMMENT + stringifyToml(document);
}

function requiredString(
  attributes: Record<string, unknown>,
  field: string,
  path: string,
): string {
  const value = attributes[field];
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${path}: native agent requires a non-empty string '${field}'.`);
  }
  return value;
}

function nativeAgent(
  name: string,
  expectedName: string,
  description: string,
  body: string,
  path: string,
  target: TargetName,
  overlay: TargetOverlay,
): CanonicalAgent {
  return {
    version: 1,
    name,
    description,
    body,
    path,
    valid:
      name === expectedName &&
      isPortableAgentName(name) &&
      description.trim().length > 0 &&
      body.trim().length > 0,
    targets: target === "claude"
      ? { claude: overlay, codex: {} }
      : { claude: {}, codex: overlay },
  };
}

/** Parse a Claude Markdown subagent while retaining every native-only field. */
export function parseClaudeAgent(
  source: string,
  expectedName: string,
  path: string,
): CanonicalAgent {
  const { attributes, body } = parseFrontmatter(source, path);
  const name = requiredString(attributes, "name", path);
  const description = requiredString(attributes, "description", path);
  const overlay = entriesObject(
    Object.entries(attributes).filter(([key]) => key !== "name" && key !== "description"),
  );
  return nativeAgent(name, expectedName, description, body, path, "claude", overlay);
}

/** Parse a Codex TOML custom agent while retaining every native config field. */
export function parseCodexAgent(
  source: string,
  expectedName: string,
  path: string,
): CanonicalAgent {
  let parsed: unknown;
  try {
    parsed = parseToml(source);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`${path}: invalid TOML agent: ${message}`, { cause: error });
  }
  if (!isObject(parsed)) throw new TypeError(`${path}: TOML agent must be a table.`);

  const name = requiredString(parsed, "name", path);
  const description = requiredString(parsed, "description", path);
  const body = requiredString(parsed, "developer_instructions", path);
  const overlay = entriesObject(
    Object.entries(parsed).filter(
      ([key]) => key !== "name" && key !== "description" && key !== "developer_instructions",
    ),
  );
  return nativeAgent(name, expectedName, description, body, path, "codex", overlay);
}

/** Deterministically serialize an adopted agent back into canonical Markdown. */
export function renderCanonicalAgent(agent: CanonicalAgent): string {
  assertCommonFields(agent);
  const targets = entriesObject([
    ["claude", agent.targets.claude === false ? false : orderedYamlValue(agent.targets.claude, new Set())],
    ["codex", agent.targets.codex === false ? false : orderedYamlValue(agent.targets.codex, new Set())],
  ]);
  const attributes = entriesObject([
    ["version", 1],
    ["name", agent.name],
    ["description", agent.description],
    ["targets", targets],
  ]);
  return `---\n${yamlDocument(attributes)}---\n\n${normalizeBody(agent.body)}`;
}
